import recorded from "../content/demo-responses.json";
import type { PromptSpec } from "../content/types";
import { promptHash } from "./hash";

// Demo mode: recorded answers for unedited lesson examples, so learners without
// an API key can still see what Claude says. Generated by scripts/record-demos.ts
// from real API calls; never hand-written.

export interface DemoEntry {
  hash: string;
  text: string;
  thinking?: string;
  model: string;
  recordedAt: string;
}

const store = recorded as Record<string, DemoEntry>;

/** The recorded answer for this example, if it exists and the prompt is unchanged. */
export function getDemo(exampleId: string, spec: PromptSpec): DemoEntry | null {
  const e = store[exampleId];
  if (!e) return null;
  return e.hash === promptHash(spec) ? e : null;
}

export const demoCount = () => Object.keys(store).length;
